def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0])
    cnt=Counter(x for row in grid for x in row)
    bg=cnt.most_common(1)[0][0]
    mark=min((x for x in cnt if x!=bg),key=cnt.get)
    out=[r[:] for r in grid]
    for r in range(h):
        cs=[c for c in range(w) if grid[r][c]==mark]
        for a,b in zip(cs,cs[1:]):
            for c in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=2
    for c in range(w):
        rs=[r for r in range(h) if grid[r][c]==mark]
        for a,b in zip(rs,rs[1:]):
            for r in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=2
    return out
